def write_all(stream, data):
    total_length = len(data)
    view = memoryview(data)
    offset = 0
    while offset < total_length:
        n_written = stream.write(view[offset:])
        if n_written is None:
            continue
        if n_written == 0:
            raise BlockingIOError("stream.write returned zero bytes")
        offset += n_written
    return total_length

import posixpath
from pathlib import PurePosixPath

def within_root(root, path):
    base = PurePosixPath(posixpath.normpath(root))
    candidate = PurePosixPath(posixpath.normpath(path))
    try:
        candidate.relative_to(base)
        return True
    except ValueError:
        return False

